To address the problem of calculating the sum of even numbers between 1 and 100 and finding the average of odd numbers within the same range, while demonstrating proficiency in modular design principles such as loose coupling, high cohesion, and separation of concerns, a candidate might structure their Python code as follows:

```python
# Define a class to encapsulate the calculations and adhere to the principle of high cohesion
class NumberCalculations:
    def __init__(self):
        self.sum_even = 0
        self.sum_odd = 0

    # Method to calculate the sum of even numbers
    def calculate_sum_even(self, start, end):
        for num in range(start, end + 1):
            if num % 2 == 0:
                self.sum_even += num
        return self.sum_even

    # Method to calculate the average of odd numbers
    def calculate_average_odd(self, start, end):
        for num in range(start, end + 1):
            if num % 2 != 0:
                self.sum_odd += num
        return self.sum_odd / (end - start + 1)

# Create an instance of the class
